from typing import List

def move_one_ball(arr: List[int]) -> bool:
    if not arr:
        return True

    n = len(arr)
    i = n - 2

    while i >= 0 and arr[i] <= arr[i + 1]:
        i -= 1

    if i == -1:
        return True

    j = n - 1
    while arr[i] > arr[j]:
        j -= 1

    arr[i], arr[j] = arr[j], arr[i]

    i += 1
    while i < j:
        arr[i], arr[j] = arr[j], arr[i]
        i += 1
        j -= 1

    return arr == sorted(arr)
