def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string into a list of characters
    characters = test.split()

    # Create an empty dictionary to store the histogram
    histogram_dict = {}

    # Iterate over each character in the list
    for char in characters:
        if char in histogram_dict:
            # If the character is already in the dictionary, increment its count
            histogram_dict[char] += 1
        else:
            # If the character is not in the dictionary, add it with a count of 1
            histogram_dict[char] = 1

    # Find the maximum count and its corresponding keys
    max_count = max(histogram_dict.values())
    max_keys = [key for key, value in histogram_dict.items() if value == max_count]

    # Return the dictionary with the most common letter and its count
    return {key: max_count for key in max_keys}

