from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    rows = [0] * n
    cols = [0] * n
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    memo = {}

    def dfs(i, j, path, path_length):
        if path_length == k:
            return path
        if (i, j, path_length) in memo:
            return memo[(i, j, path_length)]

        min_value = float('inf')
        for dx, dy in directions:
            x, y = i + dx, j + dy
            if 0 <= x < n and 0 <= y < n:
                new_path = path + [grid[x][y]]
                new_length = path_length + 1
                result = dfs(x, y, new_path, new_length)
                if len(result) < len(path) or (len(result) == len(path) and result < path):
                    min_value = min(min_value, result[path_length])

        memo[(i, j, path_length)] = min_value
        return min_value

    min_length = float('inf')
    for i in range(n):
        for j in range(n):
            path = [grid[i][j]]
            path_length = 1
            min_value = dfs(i, j, path, path_length)
            if len(min_value) < len(path) or (len(min_value) == len(path) and min_value < path):
                min_length = min(min_length, len(min_value))

    if min_length == float('inf'):
        return []
    else:
        result = []
        for i in range(n):
            for j in range(n):
                if len(dfs(i, j, [], 0)) == min_length:
                    result.append(grid[i][j])
        return result
