from typing import List, Tuple

def find_max(words: List[str]) -> str:
    def compare_strings(s1: str, s2: str) -> int:
        n1, n2 = len(s1), len(s2)
        if n1 > n2:
            return 1
        elif n1 < n2:
            return -1
        else:
            for i in range(n1):
                if s1[i] != s2[i]:
                    return 1 if s1[i] < s2[i] else -1
            return 0

    words.sort(key=cmp_to_key(compare_strings))
    return words[0]
