def do_algebra(operator, operand):
    if len(operand) != len(operator) + 1:
        raise ValueError("Operand list must have one more element than operator list.")

    result = operand[0]
    for i in range(len(operator)):
        result = apply_operator(operator[i], result, operand[i + 1])

    return result

def apply_operator(operator, left_operand, right_operand):
    if operator == '+':
        return left_operand + right_operand
    elif operator == '-':
        return left_operand - right_operand
    elif operator == '*':
        return left_operand * right_operand
    elif operator == '//':
        return left_operand // right_operand
    elif operator == '**':
        return left_operand ** right_operand
    else:
        raise ValueError(f"Unsupported operator: {operator}")
